```javascript
const express=require("express");
const axios=require("axios");
const cors=require("cors");
require("dotenv").config();
const path=require("path");
const app=express();
const allowedOrigins=process.env.ALLOWED_ORIGINS.split(",").map(o=>o.trim());
app.use(express.json());
app.use(cors({origin:allowedOrigins}));
app.use(express.static(path.join(__dirname,".")));
app.post("/api/coinbase/onramp/start",async(req,res)=>{
  try{
    const{amountHUF,asset}=req.body;
    const quoteResp=await axios.get("",{
      headers:{Authorization:`Bearer ${process.env.COINBASE_API_KEY}`},
      params:{amount:amountHUF,payment_currency:"HUF",asset,country:"HU"}
    });
    const quoteId=quoteResp.data.id;
    const sessionResp=await axios.post("",{quoteId},{
      headers:{Authorization:`Bearer ${process.env.COINBASE_API_SECRET}`}
    });
    res.json({sessionToken:sessionResp.data.token});
  }catch(e){
    res.status(500).json({error:e.message});
  }
});
const PORT=process.env.PORT||3000;
app.listen(PORT);
